import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { ToggleSwitch } from "./toggle-switch";
import { useState } from "react";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Toggle Switch",
  component: ToggleSwitch,
  parameters: {
    docs: {
      description: {
        component:
          "On/off switch with an optional label and a spring-animated handle. The state is fully " +
          "controlled: the switch reports clicks via `onClick` and renders whatever `isOn` says.",
      },
    },
  },
  render: function RenderComponent(args) {
    const [isOn, setIsOn] = useState(args.isOn);
    return <ToggleSwitch {...args} isOn={isOn} onClick={() => setIsOn((prev) => !prev)} />;
  },
  args: {
    label: "Toggle me",
    isOn: false,
    contentfulLabelId: undefined,
    onClick: fn(),
  },
} satisfies Meta<typeof ToggleSwitch>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantIsOn: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="isOn" variantType="prop">
      <Variant label="false">
        <ToggleSwitch {...args} label="Off" isOn={false} />
      </Variant>
      <Variant label="true">
        <ToggleSwitch {...args} label="On" isOn={true} />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onClickSpy = fn();

export const TestToggle: Story = {
  args: {
    label: "Notiser",
  },
  render: function RenderComponent(args) {
    const [isOn, setIsOn] = useState(false);
    return (
      <ToggleSwitch
        {...args}
        isOn={isOn}
        onClick={() => {
          onClickSpy();
          setIsOn((prev) => !prev);
        }}
      />
    );
  },
  play: async ({ canvasElement }) => {
    onClickSpy.mockClear();
    const canvas = within(canvasElement);
    const switchButton = canvas.getByRole("button");
    await expect(switchButton).toHaveAttribute("aria-pressed", "false");
    await userEvent.click(switchButton);
    await expect(onClickSpy).toHaveBeenCalledTimes(1);
    await expect(switchButton).toHaveAttribute("aria-pressed", "true");
  },
};
