import { motion } from "framer-motion";
import styles from "./toggle-switch.module.less";

type ToggleSwitchProps = {
  /** Controlled on/off state. The switch never toggles itself, flip this from `onClick` */
  isOn: boolean;
  label?: string;
  contentfulLabelId?: string;
  onClick: () => void;
};

export const ToggleSwitch = ({ isOn, label, contentfulLabelId, onClick }: ToggleSwitchProps) => {
  return (
    <div className={styles.wrapper}>
      <label data-contentful-label-id={contentfulLabelId} className={`${styles.label} body-s`}>
        {label}
      </label>
      <button className={styles.switch} aria-pressed={isOn} data-ison={isOn} onClick={onClick}>
        <motion.div
          className={styles.handle}
          layout
          transition={{
            type: "spring",
            stiffness: 400,
            damping: 30,
          }}
        />
      </button>
    </div>
  );
};
